1199:                                              const t_physical_tile_loc& compressed_loc,
1200:                                              float rlim) {
1201:     t_bb search_ranges;
1202:     int layer_num = compressed_loc.layer_num;
1203:     VTR_ASSERT(compressed_loc.x != OPEN && compressed_loc.y != OPEN && compressed_loc.layer_num != OPEN);
1204: 
1205:     int rlim_x_max_range = std::min<int>((int)compressed_block_grid.get_num_columns(layer_num), rlim);
1206:     int rlim_y_max_range = std::min<int>((int)compressed_block_grid.get_num_rows(layer_num), rlim); /* for aspect_ratio != 1 case. */
1207: 
1208:     search_ranges.xmin = std::max(0, compressed_loc.x - rlim_x_max_range);
1209:     search_ranges.xmax = std::min<int>(compressed_block_grid.get_num_columns(layer_num) - 1, compressed_loc.x + rlim_x_max_range);
1210: 
1211:     search_ranges.ymin = std::max(0, compressed_loc.y - rlim_y_max_range);
1212:     search_ranges.ymax = std::min<int>(compressed_block_grid.get_num_rows(layer_num) - 1, compressed_loc.y + rlim_y_max_range);
1213: 
1214:     search_ranges.layer_min = compressed_loc.layer_num;
1215:     search_ranges.layer_max = compressed_loc.layer_num;
1216: 
1217:     return search_ranges;
1218: }
